-- scripts/ci/fixture.sql  — GENERATED, do not hand-edit.
--
-- A deterministic synthetic price series and the values an independent implementation computes
-- from it. Generated once (seed 20260914) and committed, so the expected numbers below are fixed
-- forever and any drift in the SQL shows up as a failing check.
--
-- WHY SYNTHETIC AND NOT REAL PRICES: the data plan is licensed for individual use, so committing a
-- real ticker's OHLC history to a public repo would be redistribution. Four derived indicator
-- values in DEFINITIONS.md are fine; a price series is not. This is a licensing constraint, not a
-- technical preference.
--
-- WHAT THIS DOES AND DOES NOT PROVE. It proves the FORMULAS: that our SQL computes Wilder's RSI,
-- the EMA seeding, the window frames and the annualisation the way an independent implementation
-- written from DEFINITIONS.md does. It proves nothing about the vendor's data or the adjustment
-- basis - that is what the MU golden values do, and they stay a manual check against production
-- because CI has no business reaching live data.
--
-- The series is shaped to hit the edges rather than to look realistic: a steady uptrend, a sharp
-- drawdown that drives RSI low and pushes price far off its high, a dead-flat stretch where RSI is
-- undefined, and a gap up that drives RSI high.



-- Degenerate companions. FLAT has no movement at all (RSI undefined, not 50); SHORT sits below
-- every warm-up window; ^IDX is close-only, the shape FRED delivers.
  select 'FLAT', date '2024-01-01' + g, 50, 50, 50, 50, 1000, 'fixture' from generate_series(0,199) g;
  select 'SHORT', date '2024-01-01' + g, 20, 21, 19, 20, 1000, 'fixture' from generate_series(0,9) g;
  select '^IDX', date '2024-01-01' + g, 15 + g * 0.05, 'fred' from generate_series(0,199) g;

-- Expected values, computed by the reference implementation at generation time.
create table ci_expected (
  d date not null, param text not null, expected double precision, primary key (d, param)
);
